import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.DYPTBNgj.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md"}'),n={name:"getting-started/installation.md"};function s(r,e,l,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Aerini installs like any other desktop app: download a file, open it, and you&#39;re running. No terminal, no compiler, no account to create. Building from source is possible too, but it&#39;s a separate path for contributors, covered lower on this page.</p><h2 id="download-the-installer" tabindex="-1">Download the installer <a class="header-anchor" href="#download-the-installer" aria-label="Permalink to &quot;Download the installer&quot;">​</a></h2><p>Every release is published on the <a href="https://github.com/Panchak2d/aerini/releases" target="_blank" rel="noreferrer">Releases page</a>. Pick the file that matches your operating system, and take the one marked <strong>Recommended</strong> if you&#39;re unsure. The release notes list the files grouped by system (Windows, macOS, Linux), so you don&#39;t have to scroll through every attached file.</p><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><ol><li>Download the <code>.dmg</code> file from Releases.</li><li>Open it and drag Aerini into your Applications folder.</li><li>Launch Aerini from Applications (or Spotlight).</li></ol><p>Aerini&#39;s macOS build isn&#39;t signed with an Apple Developer certificate, so the first launch triggers Gatekeeper. Instead of double-clicking, right-click (or Control-click) the Aerini icon and choose <strong>Open</strong>, then choose <strong>Open</strong> again in the dialog that follows. You only need to do this once; after that it opens normally.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The current macOS release is built for Apple Silicon (M1 and later). An Intel Mac build isn&#39;t published yet. If you&#39;re on an Intel Mac, building from source (below) is the only option for now.</p></div><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><ol><li>Download either the <code>.msi</code> or the <code>.exe</code> from Releases. Both install the same app; pick whichever you&#39;re used to running.</li><li>Run the installer.</li></ol><p>The installer isn&#39;t code-signed, so Windows Defender SmartScreen will probably step in with a warning the first time you run it. Click <strong>More info</strong>, then <strong>Run anyway</strong> to continue. This is normal for a small open-source project without a paid code-signing certificate, not a sign that anything is wrong.</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><ol><li>Download the <code>.deb</code> (Debian, Ubuntu, and derivatives) or the <code>.AppImage</code> (most other distributions) from Releases.</li><li>For <code>.deb</code>: double-click it to open your distribution&#39;s graphical package installer, or install it from a terminal with <code>sudo apt install ./&lt;the-file-you-downloaded&gt;.deb</code>.</li><li>For <code>.AppImage</code>: make it executable (<code>chmod +x Aerini*.AppImage</code>) and run it directly. No installation step needed.</li></ol><p>Aerini&#39;s window is rendered with <code>webkit2gtk</code> (version 4.1). Most desktop Linux installations already have it, since plenty of other apps depend on it too. If Aerini fails to launch with an error mentioning a missing shared library, install your distribution&#39;s <code>webkit2gtk-4.1</code> runtime package (for example, <code>libwebkit2gtk-4.1-0</code> on Debian and Ubuntu) and try again.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Once you&#39;re running a release that includes in-app updates, later versions install from <strong>Settings → About → Updates</strong>; you don&#39;t need to repeat the steps above. Aerini 0.4.1 and earlier have no in-app updater, so install the first release that has one this way. See <a href="./../operations/updating#desktop-app">Updating</a>.</p></div><h2 id="building-from-source" tabindex="-1">Building from source <a class="header-anchor" href="#building-from-source" aria-label="Permalink to &quot;Building from source&quot;">​</a></h2><p>This section is for contributors, or for a platform the installer doesn&#39;t cover yet (like Intel Macs today). Most people should use the installer above instead.</p><p>You&#39;ll need:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Version</th></tr></thead><tbody><tr><td>Rust (stable)</td><td>1.96+</td></tr><tr><td>Node.js</td><td>20.19+ or 22.12+ to build; 22.12+, 24, or 26+ to run the tests</td></tr><tr><td>Tauri CLI</td><td>2.x</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Panchak2d/aerini</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aerini</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/fetch-node-binaries.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p><code>fetch-node-binaries.sh</code> downloads and verifies the Node.js runtime that Aerini bundles for its Code (JS) node. It&#39;s a one-time step per clone, and the build fails without it. The first build takes a few minutes while Rust compiles; later changes rebuild in seconds. Full details, including how to produce a standalone installer yourself, live in <code>CONTRIBUTING.md</code> at the repository root.</p><h2 id="uninstalling" tabindex="-1">Uninstalling <a class="header-anchor" href="#uninstalling" aria-label="Permalink to &quot;Uninstalling&quot;">​</a></h2><p>Removing the app itself is the usual process for your OS: drag it to the Trash on macOS, use <em>Add or Remove Programs</em> on Windows, or remove the package with your package manager on Linux (for example, <code>sudo apt remove aerini</code>), or just delete the AppImage file if that&#39;s how you installed it.</p><p>Uninstalling the app doesn&#39;t delete your workflows, credentials, or settings. Those live in a separate data folder:</p><table tabindex="0"><thead><tr><th>OS</th><th>Location</th></tr></thead><tbody><tr><td>macOS</td><td><code>~/Library/Application Support/org.aerini.desktop</code></td></tr><tr><td>Windows</td><td><code>%APPDATA%\\org.aerini.desktop</code></td></tr><tr><td>Linux</td><td><code>~/.local/share/org.aerini.desktop</code></td></tr></tbody></table><p>Delete that folder too if you want a completely clean removal. One thing it won&#39;t contain: the encryption key for your stored credentials sits in your OS <a href="./../glossary#keyring">keyring</a> (macOS Keychain, Windows Credential Manager, or Linux Secret Service) rather than in that folder, so a thorough wipe means clearing it from there as well if your keyring manager makes that easy to do.</p><p>If you turned on <strong>Launch at login</strong> in Settings, it&#39;s worth switching that off before you uninstall, so nothing tries to start Aerini after it&#39;s gone.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p>Head to <a href="./getting-started">Getting Started</a> to build and run your first workflow.</p>`,29)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
